while (Signal.WaitStart())
{
    ActionNode actionNode = this.S1ActionNodeController.GetNextActionNode();

    // 没有actionNode了，代表全部都已经做完了，直接退出
    if (actionNode == null)
    {
        break;
    }

    if (!actionNode.IsDoWork())
    {
