        if (MachineStateModel.GetInstance().MachineWorkMode == MachineWorkModeEnum.OffLineWork)
        {
            // 修改当前焊点的状态为点胶完成
            this.BondPosition.S1FinishedStep(this.ActionNodeController.SingleProcessStepName);
