    // 添加旋转和偏移
    for (int i = 0; i < epoxy.DispensePatternParas.Count; i++)
    {
        for (int j = 0; j < epoxy.DispensePatternParas[i].Length; j++)
        {
            EpoxyApplicationLocation location = epoxy.DispensePatternParas[i][j];

            double x = location.X;
