public static List<List<int>> GetCycleList(int totalNumber, int cycleNumber)
{
    List<List<int>> list = new List<List<int>>();
    for (int i = 0; i < totalNumber; i++)
    {
        List<int> cycleList = new List<int>();
        for (int j = 0; j < cycleNumber; j++)
        {
            if (i < totalNumber)
            {
                cycleList.Add(i);
                i++;
            }
        }

        i--;
        list.Add(cycleList);
    }

    return list;
}

