        this.SlowUpToLiftLevel(liftPreLevel, pickActionParameter);

        System2RunTimeProvider.RecordTime("Pick", $"焊头低速上抬结束");
    }

    System2RunTimeProvider.RecordTime("Pick", $"取片动作完成");
}

